with valid as (select id, order_date, status, channel, amount, discount, floor(discount) as discount_whole, substring(channel, 1, 2) as channel_prefix from orders where order_date >= date '2023-08-04' and customer_id is not null) select status, case when discount >= 0.34 then 'HIGH' else 'LOW' end as discount_tier, approx_percentile(amount, 0.95) as amount_p95, count(case when status = 'PENDING' then 1 end) as pending_count, size(collect_set(channel)) as num_channels, sort_array(collect_set(status)) as status_list, sum(case when channel = 'store' then amount else 0 end) as store_amount, rank() over (partition by status order by sum(case when channel = 'store' then amount else 0 end) desc) as store_amount_rank from valid group by status, discount_tier order by discount_tier desc
